<script setup>
import { computed, ref, watch } from 'vue';

const props = defineProps({ mode: { type: String, required: true }, completado: { type: Boolean, default: false } });
const emit = defineEmits(['hablar', 'practicar']);
const paso=ref(1),personaId=ref('i'),planId=ref('cook'),momentoId=ref('tonight'),retoIdx=ref(0),elegida=ref(null),aciertos=ref(new Set()),tipoGoing=ref('plan');
const personas=[{id:'i',texto:'I',be:'am',corto:"I'm",icono:'🙋'},{id:'she',texto:'She',be:'is',corto:"She's",icono:'👩'},{id:'he',texto:'He',be:'is',corto:"He's",icono:'👨'},{id:'we',texto:'We',be:'are',corto:"We're",icono:'👥'},{id:'they',texto:'They',be:'are',corto:"They're",icono:'🧑‍🤝‍🧑'}];
const planes=[{id:'cook',base:'cook dinner',ing:'cooking dinner',icono:'🍲'},{id:'visit',base:'visit my family',ing:'visiting my family',icono:'👨‍👩‍👧'},{id:'travel',base:'travel to the beach',ing:'traveling to the beach',icono:'🏖️'},{id:'buy',base:'buy a new bicycle',ing:'buying a new bicycle',icono:'🚲'},{id:'watch',base:'watch a movie',ing:'watching a movie',icono:'🎬'}];
const momentos=[{id:'tonight',texto:'tonight',icono:'🌙'},{id:'tomorrow',texto:'tomorrow',icono:'🌅'},{id:'saturday',texto:'on Saturday',icono:'📅'},{id:'eight',texto:'at 8 PM',icono:'🕗'}];
const persona=computed(()=>personas.find(x=>x.id===personaId.value)),plan=computed(()=>planes.find(x=>x.id===planId.value)),momento=computed(()=>momentos.find(x=>x.id===momentoId.value));
const fraseGoing=computed(()=>`${persona.value.texto} ${persona.value.be} going to ${plan.value.base} ${momento.value.texto}.`);
const fraseWill=computed(()=>`${persona.value.texto === 'I' ? "I'll" : `${persona.value.texto} will`} ${plan.value.base} ${momento.value.texto}.`);
const fraseArrangement=computed(()=>`${persona.value.corto} ${plan.value.ing} ${momento.value.texto}.`);
const ejemploGoing=computed(()=>tipoGoing.value==='plan'?"We're going to travel on Saturday.":"It's going to rain.");
const meta=computed(()=>({
  going:{icono:'🧭',sobre:'PLAN O EVIDENCIA',titulo:'Going to: el futuro ya se ve',bajada:'Usalo para intenciones decididas y predicciones con señales presentes.',tabs:['Armá el plan','Plan vs. evidencia','Reto going to']},
  will:{icono:'💡',sobre:'DECISIÓN INSTANTÁNEA',titulo:'Will y shall',bajada:'Decisiones del momento, promesas, ofrecimientos y predicciones generales.',tabs:['Decidí ahora','Will vs. shall','Reto espontáneo']},
  arrangement:{icono:'📆',sobre:'PLAN ACORDADO',titulo:'Presente continuo con futuro',bajada:'Un plan organizado con día, hora o personas involucradas.',tabs:['Agendá el plan','Escala de certeza','Reto de agenda']},
}[props.mode]));
const retos=computed(()=>({
  going:[{icono:'🎟️',frase:"We bought the tickets. We ___ travel on Saturday.",respuesta:'are going to',opciones:['will','are going to','are','shall'],ayuda:'Los boletos muestran que el plan ya está decidido.'},{icono:'☁️',frase:'Look at those clouds! It ___ rain.',respuesta:'is going to',opciones:['will to','is going to','is raining to','shall'],ayuda:'Las nubes son evidencia visible.'},{icono:'🍲',frase:'She ___ cook dinner tonight.',respuesta:'is going to',opciones:['are going to','is going to','will to','going'],ayuda:'She usa is going to.'}],
  will:[{icono:'📞',frase:'The phone is ringing. I ___ answer it.',respuesta:'will',opciones:['will','am going to','am','shall to'],ayuda:'La decisión nace en este momento.'},{icono:'🤝',frase:"Don't worry. I ___ help you.",respuesta:'will',opciones:['am','will','going','do'],ayuda:'Will también expresa una promesa.'},{icono:'🍵',frase:'___ I make some tea?',respuesta:'Shall',opciones:['Will to','Am','Shall','Do'],ayuda:'Shall I…? sirve para ofrecer algo.'}],
  arrangement:[{icono:'🍽️',frase:'We ___ Marta at 8 PM.',respuesta:'are meeting',opciones:['meet','will meet','are meeting','meeting'],ayuda:'La hora concreta indica un plan acordado.'},{icono:'🏖️',frase:'She ___ to the beach on Saturday.',respuesta:'is traveling',opciones:['travels','is traveling','will traveling','traveling'],ayuda:'She usa is + verbo-ing.'},{icono:'🎬',frase:'I ___ a movie with Ana tonight.',respuesta:'am watching',opciones:['watch','am watching','is watching','will watching'],ayuda:'I usa am + verbo-ing.'}],
}[props.mode]));
const reto=computed(()=>retos.value[retoIdx.value]),correcta=computed(()=>elegida.value===reto.value.respuesta);
function escuchar(t){emit('hablar',t,1)}function responder(o){elegida.value=o;if(o===reto.value.respuesta)aciertos.value=new Set([...aciertos.value,retoIdx.value])}function siguiente(){retoIdx.value=(retoIdx.value+1)%retos.value.length;elegida.value=null}watch(()=>props.mode,()=>{paso.value=1;retoIdx.value=0;elegida.value=null;aciertos.value=new Set()});
</script>

<template><section class="future" :class="`future--${mode}`"><aside class="hero"><span>{{meta.icono}}</span><div><small>ADULTO ESTÁNDAR · {{meta.sobre}}</small><h2>{{meta.titulo}}</h2><p>{{meta.bajada}}</p></div><div class="arrow"><b>NOW</b><i>━━━━▶</i><span>NEXT</span></div></aside><nav><button v-for="(tab,i) in meta.tabs" :key="tab" :class="{active:paso===i+1}" @click="paso=i+1"><b>0{{i+1}}</b><span>{{tab}}</span></button></nav>

<main v-if="paso===1"><header><small>FUTURO 1</small><h3>{{meta.tabs[0]}}</h3><p>Elegí quién, qué hará y cuándo. La estructura se arma en vivo.</p></header><div class="builder"><section><button v-for="x in personas" :key="x.id" :class="{active:personaId===x.id}" @click="personaId=x.id">{{x.icono}} <b>{{x.texto}}</b></button></section><section><button v-for="x in planes" :key="x.id" :class="{active:planId===x.id}" @click="planId=x.id">{{x.icono}} <b>{{x.base}}</b></button></section><section><button v-for="x in momentos" :key="x.id" :class="{active:momentoId===x.id}" @click="momentoId=x.id">{{x.icono}} <b>{{x.texto}}</b></button></section></div><article class="result"><span>{{persona.icono}} {{plan.icono}} {{momento.icono}}</span><small>{{mode==='going'?'DECIDED':mode==='will'?'DECIDED NOW':'ARRANGED'}}</small><strong>{{mode==='going'?fraseGoing:mode==='will'?fraseWill:fraseArrangement}}</strong><button @click="escuchar(mode==='going'?fraseGoing:mode==='will'?fraseWill:fraseArrangement)">🔊 Escuchar plan</button></article><aside v-if="mode==='will'" class="note"><b>Contracción natural:</b> I will → I'll · she will → she'll · we will → we'll.</aside></main>

<main v-else-if="paso===2 && mode==='going'"><header><small>GOING TO 2</small><h3>Dos caminos hacia la misma estructura</h3><p>La intención puede venir de una decisión previa o de evidencia visible.</p></header><div class="choice"><button :class="{active:tipoGoing==='plan'}" @click="tipoGoing='plan'"><span>🧳</span><b>PLAN DECIDIDO</b><small>I bought the tickets.</small></button><button :class="{active:tipoGoing==='evidence'}" @click="tipoGoing='evidence'"><span>🌧️</span><b>EVIDENCIA PRESENTE</b><small>Look at those clouds!</small></button></div><article class="prediction"><span>{{tipoGoing==='plan'?'🎟️ → 🏖️':'☁️ → 🌧️'}}</span><b>{{ejemploGoing}}</b><button @click="escuchar(ejemploGoing)">🔊</button></article><div class="formula"><b>subject</b><i>＋</i><strong>am / is / are going to</strong><i>＋</i><b>base verb</b></div></main>
<main v-else-if="paso===2 && mode==='will'"><header><small>WILL / SHALL 2</small><h3>Qué expresa cada uno</h3><p>Will es común para todos los sujetos; shall sobrevive sobre todo en preguntas con I y we.</p></header><div class="use-grid"><article><span>💡</span><b>DECISIÓN AHORA</b><p>I'm thirsty. I'll get some water.</p></article><article><span>🤝</span><b>PROMESA</b><p>I'll call you tonight.</p></article><article><span>🔮</span><b>PREDICCIÓN</b><p>I think it will be sunny.</p></article><article><span>🍵</span><b>OFERTA / SUGERENCIA</b><p>Shall I make some tea?</p></article></div><aside class="note"><b>Shall</b> es menos frecuente y se usa principalmente en <i>Shall I…?</i> y <i>Shall we…?</i></aside></main>
<main v-else-if="paso===2"><header><small>AGENDA 2</small><h3>Escala de certeza</h3><p>El presente continuo suena a plan concreto: ya hay hora, lugar o acuerdo.</p></header><div class="certainty"><article><small>IDEA</small><b>Maybe I'll visit Ana.</b><span>💭</span></article><i>→</i><article><small>INTENCIÓN</small><b>I'm going to visit Ana.</b><span>🧭</span></article><i>→</i><article><small>ACORDADO</small><b>I'm visiting Ana at 6 PM.</b><span>📆</span></article></div><div class="formula"><b>subject</b><i>＋</i><strong>am / is / are</strong><i>＋</i><b>verb-ing</b><i>＋</i><span>future time</span></div></main>

<main v-else><header class="challenge-head"><div><small>{{meta.sobre}} · RETO</small><h3>{{meta.tabs[2]}}</h3><p>Buscá si hay decisión previa, reacción inmediata o plan agendado.</p></div><b>{{aciertos.size}}/{{retos.length}}</b></header><article class="challenge"><span>{{reto.icono}}</span><button @click="escuchar(reto.frase.replace('___',reto.respuesta))">{{reto.frase}} 🔊</button><div><button v-for="o in reto.opciones" :key="o" :class="{ok:elegida&&o===reto.respuesta,bad:elegida===o&&o!==reto.respuesta}" @click="responder(o)">{{o}}</button></div><p v-if="elegida"><b>{{correcta?'✓ Futuro conectado':'↻ Revisá la situación'}}</b> {{reto.ayuda}}</p><button v-if="correcta" class="next" @click="siguiente">Siguiente plan →</button></article></main><button class="practice" :disabled="completado" @click="emit('practicar')">{{completado?'✓ Ejercicios ya acreditados':'Practicar ejercicios del workbook →'}}</button></section></template>

<style scoped>
.future{display:grid;gap:1rem;--accent:#b0632c;--soft:#fff2df;--cool:#eaf4ff}.future--will{--accent:#6b5797;--soft:#f2edfa;--cool:#eaf7f4}.future--arrangement{--accent:#31768b;--soft:#e8f5f8;--cool:#f1edfb}.hero,main{padding:1rem;border:1px solid #decfbd;border-radius:var(--radio-panel);background:var(--color-superficie)}.hero{display:grid;grid-template-columns:auto 1fr auto;align-items:center;gap:.8rem;background:linear-gradient(135deg,var(--soft),var(--cool))}.hero>span{font-size:2.7rem}.hero h2,main h3{margin:.15rem 0}.hero p,main header p{margin:.25rem 0;color:var(--color-texto-secundario)}small{font-size:.62rem;font-weight:900;letter-spacing:.08em;color:var(--accent)}.arrow{display:flex;align-items:center;gap:.3rem;padding:.6rem;border:1px dashed var(--accent);border-radius:10px;color:var(--accent);font-size:.62rem}nav{display:grid;grid-template-columns:repeat(3,1fr);gap:.5rem}nav button{display:flex;gap:.5rem;padding:.7rem;border:1px solid var(--color-borde);border-radius:12px;background:var(--color-superficie);text-align:left}nav button b{color:var(--accent)}nav button.active,.builder button.active,.choice button.active{border-color:var(--accent)!important;background:var(--soft)!important}.builder{display:grid;gap:.6rem}.builder section{display:flex;flex-wrap:wrap;gap:.4rem}.builder button{padding:.5rem .65rem;border:1px solid var(--color-borde);border-radius:9px;background:var(--color-superficie)}.result{display:flex;flex-direction:column;align-items:center;gap:.3rem;margin-top:.8rem;padding:1rem;border-radius:15px;background:linear-gradient(145deg,var(--soft),var(--cool));text-align:center}.result>span{font-size:2.2rem}.result strong{font:italic 1.15rem Georgia}.result button,.prediction button{padding:.5rem .7rem;border:0;border-radius:var(--radio-boton);background:var(--accent);color:#fff}.note{margin-top:.7rem;padding:.7rem;border-left:4px solid var(--accent);border-radius:8px;background:var(--soft);font-size:.75rem}.choice{display:grid;grid-template-columns:1fr 1fr;gap:.7rem}.choice button{display:flex;flex-direction:column;align-items:center;padding:1rem;border:1px solid var(--color-borde);border-radius:14px;background:var(--color-superficie)}.choice span{font-size:2.2rem}.prediction{display:flex;align-items:center;justify-content:center;gap:.7rem;margin:.8rem 0;padding:1rem;border-radius:14px;background:var(--cool)}.prediction>span{font-size:1.8rem}.formula{display:flex;align-items:center;justify-content:center;gap:.6rem;padding:1rem;border-radius:14px;background:var(--soft);text-align:center}.formula strong{font:italic 1.15rem Georgia;color:var(--accent)}.use-grid{display:grid;grid-template-columns:1fr 1fr;gap:.6rem}.use-grid article{display:grid;grid-template-columns:auto 1fr;gap:.3rem;padding:.8rem;border:1px solid var(--color-borde);border-radius:12px}.use-grid article>span{grid-row:1/3;font-size:1.7rem}.use-grid p{margin:0;font:italic .8rem Georgia}.certainty{display:grid;grid-template-columns:1fr auto 1fr auto 1fr;align-items:center;gap:.4rem;margin-bottom:.8rem}.certainty article{display:flex;flex-direction:column;align-items:center;padding:.8rem;border-radius:13px;background:var(--cool);text-align:center}.certainty article:last-child{background:var(--soft);box-shadow:var(--sombra-card)}.certainty article>span{font-size:1.7rem}.certainty article>b{font:italic .8rem Georgia}.challenge-head{display:flex;justify-content:space-between}.challenge-head>b{display:grid;place-items:center;width:48px;height:48px;border-radius:50%;background:var(--soft);color:var(--accent)}.challenge{max-width:650px;margin:auto;padding:1rem;border-radius:16px;background:linear-gradient(145deg,var(--soft),var(--cool));text-align:center}.challenge>span{font-size:2.7rem}.challenge>button{display:block;margin:.4rem auto;border:0;background:transparent;font:italic 1.1rem Georgia}.challenge>div{display:grid;grid-template-columns:1fr 1fr;gap:.4rem}.challenge>div button{padding:.6rem;border:1px solid var(--color-borde);border-radius:9px;background:var(--color-superficie)}.challenge .ok{border-color:var(--color-verde);background:var(--color-verde-suave)}.challenge .bad{border-color:var(--color-rojo);background:var(--color-rojo-suave)}.next{padding:.55rem .8rem!important;background:var(--accent)!important;color:#fff!important}.practice{width:100%;padding:.8rem;border:0;border-radius:var(--radio-boton);background:var(--accent);color:#fff;font-weight:800}.practice:disabled{background:var(--color-verde)}
@media(max-width:650px){.hero{grid-template-columns:auto 1fr}.arrow{grid-column:1/-1;justify-content:center}nav,.choice,.use-grid,.challenge>div{grid-template-columns:1fr}.certainty{grid-template-columns:1fr}.certainty>i{transform:rotate(90deg);text-align:center}.formula{flex-wrap:wrap}}@media(max-width:420px){.builder section{display:grid;grid-template-columns:1fr 1fr}}
</style>
